+/**
+ * Function: sanitizeColor
+ *
+ * Returns the given color if it is safe to use in CSS/SVG color contexts,
+ * null otherwise.
+ */
+mxUtils.sanitizeColor = function(color)
+{
+	if (color == null || color == mxConstants.NONE)
+	{
+		return color;
+	}
+	
+	color = String(color);
+	
+	// Reject characters that can break out of CSS or unquoted XML/HTML
+	// attribute contexts when colors are serialized.
+	if (/[<>"'`;=]/.test(color))
+	{
+		return null;
+	}
+	
+	if (typeof(document) != 'undefined' && document.createElement != null)
+	{
+		var div = document.createElement('div');
+		div.style.color = '';
+		div.style.color = color;
+		
+		if (div.style.color != '')
+		{
+			return color;
+		}
+	}
+	else if (/^(#[0-9a-fA-F]{3,8}|[a-zA-Z][a-zA-Z0-9]*|(?:rgb|rgba|hsl|hsla)\([-+0-9.,% ]+\))$/.test(color))
+	{
+		return color;
+	}
+	
+	return null;
+};
+
