+package org.apache.streampipes.manager.endpoint;
+
+import java.net.InetAddress;
+import java.net.URI;
+import java.net.URISyntaxException;
+import java.net.UnknownHostException;
+import java.util.Locale;
+
+public final class EndpointUrlValidator {
+
+  private EndpointUrlValidator() {
+  }
+
+  public static void validate(String endpointUrl) {
+    URI uri = parse(endpointUrl);
+    validateScheme(uri);
+    validateHost(uri);
+  }
+
+  private static URI parse(String endpointUrl) {
+    try {
+      return new URI(endpointUrl);
+    } catch (URISyntaxException e) {
+      throw new IllegalArgumentException("Invalid pipeline element endpoint URL", e);
+    }
+  }
+
+  private static void validateScheme(URI uri) {
+    var scheme = uri.getScheme();
+
+    if (scheme == null) {
+      throw new IllegalArgumentException("Pipeline element endpoint URL must define a scheme");
+    }
+
+    scheme = scheme.toLowerCase(Locale.ROOT);
+
+    if (!"http".equals(scheme) && !"https".equals(scheme)) {
+      throw new IllegalArgumentException("Only HTTP(S) pipeline element endpoint URLs are allowed");
+    }
+  }
+
+  private static void validateHost(URI uri) {
+    if (uri.getUserInfo() != null) {
+      throw new IllegalArgumentException("Pipeline element endpoint URL must not contain user info");
+    }
+
+    var host = uri.getHost();
+
+    if (host == null || host.isBlank()) {
+      throw new IllegalArgumentException("Pipeline element endpoint URL must define a host");
+    }
+
+    try {
+      for (var address : InetAddress.getAllByName(host)) {
+        if (isForbiddenAddress(address)) {
+          throw new IllegalArgumentException("Pipeline element endpoint URL resolves to a forbidden address");
+        }
+      }
+    } catch (UnknownHostException e) {
+      throw new IllegalArgumentException("Pipeline element endpoint host could not be resolved", e);
+    }
+  }
+
+  private static boolean isForbiddenAddress(InetAddress address) {
+    return address.isAnyLocalAddress()
+        || address.isLoopbackAddress()
+        || address.isLinkLocalAddress()
+        || address.isSiteLocalAddress()
+        || address.isMulticastAddress()
+        || isUniqueLocalIpv6Address(address);
+  }
+
+  private static boolean isUniqueLocalIpv6Address(InetAddress address) {
+    var bytes = address.getAddress();
+
+    if (bytes.length != 16) {
+      return false;
+    }
+
+    return (bytes[0] & 0xfe) == 0xfc;
+  }
+}
