index 00000000..5f7f8c31
--- /dev/null
+++ b/lib/runtime/safePattern.ts
@@ -0,0 +1,110 @@
+const MAX_PATTERN_LENGTH = 1024
+
+interface Group {
+  hasAlt: boolean
+  hasQuantifier: boolean
+}
+
+export default function safePattern(pattern: string, flags: string, data: string): boolean {
+  if (pattern.length > MAX_PATTERN_LENGTH) return false
+
+  try {
+    new RegExp(pattern, flags)
+  } catch {
+    return false
+  }
+
+  if (hasUnsafePattern(pattern)) return false
+
+  return new RegExp(pattern, flags).test(data)
+}
+
+function hasUnsafePattern(pattern: string): boolean {
+  const stack: Group[] = []
+  let inClass = false
+  let escaped = false
+
+  for (let i = 0; i < pattern.length; i++) {
+    const ch = pattern[i]
+
+    if (escaped) {
+      if (!inClass && (isDigit(ch) || ch === "k")) return true
+      escaped = false
+      continue
+    }
+
+    if (ch === "\\") {
+      escaped = true
+      continue
+    }
+
+    if (inClass) {
+      if (ch === "]") inClass = false
+      continue
+    }
+
+    if (ch === "[") {
+      inClass = true
+      continue
+    }
+
+    if (ch === "(") {
+      if (pattern[i + 1] === "?") {
+        if (pattern[i + 2] !== ":") return true
+        i += 2
+      }
+      stack.push({hasAlt: false, hasQuantifier: false})
+      continue
+    }
+
+    if (ch === "|") {
+      if (stack.length) stack[stack.length - 1].hasAlt = true
+      continue
+    }
+
+    if (ch === ")") {
+      const group = stack.pop()
+      if (!group) continue
+
+      const qLen = quantifierLength(pattern, i + 1)
+      if (qLen && (group.hasAlt || group.hasQuantifier)) return true
+
+      if (stack.length) {
+        const parent = stack[stack.length - 1]
+        parent.hasAlt = parent.hasAlt || group.hasAlt
+        parent.hasQuantifier = parent.hasQuantifier || group.hasQuantifier || qLen > 0
+      }
+
+      if (qLen) {
+        i += qLen
+        if (pattern[i + 1] === "?") i++
+      }
+      continue
+    }
+
+    const qLen = quantifierLength(pattern, i)
+    if (qLen) {
+      if (stack.length) stack[stack.length - 1].hasQuantifier = true
+      i += qLen - 1
+      if (pattern[i + 1] === "?") i++
+    }
+  }
+
+  return false
+}
+
+function quantifierLength(pattern: string, pos: number): number {
+  const ch = pattern[pos]
+  if (ch === "*" || ch === "+" || ch === "?") return 1
+  if (ch !== "{") return 0
+
+  const end = pattern.indexOf("}", pos + 1)
+  if (end === -1) return 0
+
+  const quantifier = pattern.slice(pos, end + 1)
+  return /^\{(?:\d+,?\d*|,\d+)\}$/.test(quantifier) ? quantifier.length : 0
+}
+
+function isDigit(ch: string): boolean {
+  return ch >= "0" && ch <= "9"
+}
+
+;(safePattern as any).code = 'require("ajv/dist/runtime/safePattern").default'
